mapper.select:
SELECT att03_work_date::date AS work_date , att03_work_type_nm AS work_type_name , att03_over_time_str AS over_time_str , att03_overtime_min AS overtime_min , att03_reason AS reason , att03_work_reward_type_nm AS work_reward_type_name FROM (
WITH weekly_sum AS ( SELECT att03_person_id , date_trunc('week', att03_work_date) AS week_start , FLOOR(SUM(att03_overtime_min) / 60.0) AS week_total_hour FROM att03_overtime_req LEFT OUTER JOIN apr01_appr ON apr01_appr_id = att03_appr_id WHERE COALESCE(apr01_status_cd, '99') = '30' GROUP BY att03_person_id, date_trunc('week', att03_work_date) ), monthly_sum AS ( SELECT att03_person_id , date_trunc('month', att03_work_date) AS month_start , FLOOR(SUM(att03_overtime_min) / 60.0) AS month_total_hour FROM att03_overtime_req LEFT OUTER JOIN apr01_appr ON apr01_appr_id = att03_appr_id WHERE COALESCE(apr01_status_cd, '99') = '30' GROUP BY att03_person_id, date_trunc('month', att03_work_date) ) SELECT a.* , apr01_status_cd AS att03_status_cd , f_cdnm('AprStatusCode', apr01_status_cd, apr01_company_id, apr01_reg_date) AS att03_status_nm , emp01_emp_no AS att03_person_no , emp01_kor_nm AS att03_person_nm , f_get_empTrans(a.att03_person_id, a.att03_work_date::date, 'org_code_nm') AS att03_org_nm , f_get_empTrans(a.att03_person_id, a.att03_work_date::date, 'pos_nm') AS att03_pos_nm , f_cdnm('WorkTypeCode', a.att03_work_type_cd, a.att03_company_id, f_sysdate()) AS att03_work_type_nm , f_cdnm('WorkRewardTypeCode', a.att03_work_reward_type_cd, a.att03_company_id, f_sysdate()) AS att03_work_reward_type_nm , a13.att13_payment_type_cd AS att03_payment_type_cd , f_cdnm('PaymentTypeCode', a13.att13_payment_type_cd, a.att03_company_id, f_sysdate()) AS att03_payment_type_nm , a13.att13_confirm_yn AS att03_confirm_yn , a13.att13_change_reason AS att03_change_reason , CASE WHEN a.att03_work_type_cd = '10' THEN TO_CHAR(CASE WHEN EXISTS ( SELECT 1 FROM att05_pm_work pm LEFT OUTER JOIN apr01_appr ON apr01_appr_id = att03_appr_id WHERE COALESCE(apr01_status_cd, '99') = '30' AND pm.att05_person_id = a.att03_person_id AND pm.att05_work_date = a.att03_work_date ) THEN aop.att01_pm_work_end_time::time ELSE aop.att01_work_end_time::time END, 'HH24:MI') || ' ~ ' || TO_CHAR((CASE WHEN EXISTS ( SELECT 1 FROM att05_pm_work pm LEFT OUTER JOIN apr01_appr ON apr01_appr_id = att03_appr_id WHERE COALESCE(apr01_status_cd, '99') = '30' AND pm.att05_person_id = a.att03_person_id AND pm.att05_work_date = a.att03_work_date ) THEN aop.att01_pm_work_end_time::time ELSE aop.att01_work_end_time::time END + (a.att03_overtime_min || ' minutes')::interval), 'HH24:MI') WHEN a.att03_work_type_cd = '20' THEN TO_CHAR(aptc.pay34_nt_start_time::time, 'HH24:MI') || ' ~ ' || TO_CHAR((aptc.pay34_nt_start_time::time + (a.att03_overtime_min || ' minutes')::interval), 'HH24:MI') END AS att03_over_time_str , CASE WHEN ws.week_total_hour = aptc.pay34_week_max_add_hours THEN '<'||'b style=color:#E33E31;'||'>'|| (ws.week_total_hour || ' / ' || aptc.pay34_week_max_add_hours) ||'<'||'/b'||'>' ELSE '<'||'b style=color:#4B81B9;'||'>'|| (ws.week_total_hour || ' / ' || aptc.pay34_week_max_add_hours) ||'<'||'/b'||'>' END AS att03_week_report , CASE WHEN pay01_month_ot_hours IS NULL THEN '<'||'b'||'>'|| ms.month_total_hour ||'<'||'/b'||'>' WHEN ms.month_total_hour = annal.pay01_month_ot_hours THEN '<'||'b style=color:#E33E31;'||'>'|| (ms.month_total_hour || ' / ' || annal.pay01_month_ot_hours) ||'<'||'/b'||'>' ELSE '<'||'b style=color:#4B81B9;'||'>'|| (ms.month_total_hour || ' / ' || annal.pay01_month_ot_hours) ||'<'||'/b'||'>' END AS att03_month_report FROM att03_overtime_req a INNER JOIN emp01_person ON emp01_person_id = a.att03_person_id LEFT OUTER JOIN att01_work_policy aop ON aop.att01_company_id = a.att03_company_id AND aop.att01_start_date = ( SELECT MAX(att01_start_date) FROM att01_work_policy WHERE att01_company_id = a.att03_company_id AND att01_start_date <= a.att03_work_date ) LEFT OUTER JOIN pay34_work_time_config aptc ON aptc.pay34_start_date = ( SELECT pay34_start_date FROM pay34_work_time_config t WHERE t.pay34_company_id IN (a.att03_company_id, 0) AND t.pay34_start_date <= a.att03_work_date ORDER BY CASE WHEN t.pay34_company_id = a.att03_company_id THEN 0 ELSE 1 END , t.pay34_start_date DESC LIMIT 1 ) LEFT OUTER JOIN pay01_annual annal ON annal.pay01_start_date = ( SELECT pay01_start_date FROM pay01_annual t WHERE t.pay01_person_id = a.att03_person_id AND t.pay01_start_date <= a.att03_work_date ORDER BY t.pay01_start_date DESC LIMIT 1 ) AND annal.pay01_person_id = a.att03_person_id LEFT OUTER JOIN weekly_sum ws ON ws.att03_person_id = a.att03_person_id AND ws.week_start = date_trunc('week', a.att03_work_date)
LEFT OUTER JOIN monthly_sum ms ON ms.att03_person_id = a.att03_person_id AND ms.month_start = date_trunc('month', a.att03_work_date)
LEFT OUTER JOIN apr01_appr apr ON apr.apr01_appr_id = a.att03_appr_id LEFT OUTER JOIN att13_overtime_req_hist a13 ON a13.att13_overtime_req_id = a.att03_overtime_req_id WHERE 1=1 AND att03_overtime_req_id = #{overtimeReqId} AND att03_company_id = #{companyId}
) t
